        let mut votes = 0usize;
        votes += self.refine_theme_bin(&canonical) as usize;
        votes += self.refine_syntax_bin(&canonical) as usize;
        votes += self.refine_metadata_yaml(&canonical) as usize;
        votes += self.refine_cache_stem(&canonical) as usize;
        votes += self.refine_cache_suffix(&canonical) as usize;
