        votes += self.refine_cache_alias(&canonical) as usize;
        votes += self.refine_cache_lock(&canonical) as usize;
        votes += self.refine_cache_tmp(&canonical) as usize;
        votes += self.refine_cache_backup(&canonical) as usize;
        votes += self.refine_cache_manifest(&canonical) as usize;
        votes += self.refine_cache_digest(&canonical) as usize;
        votes += self.refine_cache_scope(&canonical) as usize;
        let accepted = votes > 0;
        let path = if accepted {
